from vim_session import run_editor
def edit(path,prefix,save):
    target=pathlib.Path(path)
    if not target.is_file() or target.is_symlink() or type(save) is not bool:raise ValueError('existing real target and explicit save mode')
    if not isinstance(prefix,str) or not 1<=len(prefix)<=80 or any(ord(c)<32 or ord(c)>126 for c in prefix):raise ValueError('bounded printable ASCII prefix')
    original=target.read_bytes()
    if not original or len(original)>4096 or not original.endswith(b'\n') or any(c!=10 and not 32<=c<=126 for c in original):raise ValueError('bounded ASCII LF file')
    command=b':wq\r' if save else b':q!\r'
    result=run_editor(target,b'\x1bgg0i'+prefix.encode('ascii')+b'\x1b'+command)
    if result['code']!=0:raise RuntimeError('Vim failed')
