import errno,fcntl,os,pathlib,pty,select,signal,struct,subprocess,termios,time
def run_editor(path,keys):
    path=pathlib.Path(path).absolute()
    if not path.is_file() or path.is_symlink() or not isinstance(keys,bytes) or not 0<len(keys)<=4096:raise ValueError('owned file and bounded key sequence required')
    master,slave=pty.openpty();child=None;output=bytearray()
    try:
        fcntl.ioctl(slave,termios.TIOCSWINSZ,struct.pack('HHHH',24,100,0,0))
        attributes=termios.tcgetattr(slave);attributes[3]&=~termios.ECHO;termios.tcsetattr(slave,termios.TCSANOW,attributes)
        child=subprocess.Popen(['/usr/bin/vi','-u','NONE','-i','NONE','-n','-N','--cmd','set nomodeline noexrc','--',str(path)],stdin=slave,stdout=slave,stderr=slave,cwd=path.parent,env={**os.environ,'TERM':'xterm'},start_new_session=True)
        os.close(slave);slave=None;deadline=time.monotonic()+3;sent=False
        while True:
            remaining=deadline-time.monotonic()
            if remaining<=0:raise RuntimeError('Vim deadline exceeded')
            ready,_,_=select.select([master],[],[],min(.05,remaining))
            if ready:
                try:data=os.read(master,4096)
                except OSError as error:
                    if error.errno==errno.EIO:break
                    raise
                if not data:break
                output.extend(data)
                if len(output)>65536:raise RuntimeError('Vim terminal output exceeded limit')
            if not sent and path.name.encode() in output:
                offset=0
                while offset<len(keys):offset+=os.write(master,keys[offset:])
                sent=True
            if child.poll() is not None and not ready:break
        code=child.wait(timeout=max(.01,deadline-time.monotonic()))
        if not sent:raise RuntimeError('Vim did not display the target buffer')
        return dict(code=code,terminal=bytes(output))
    finally:
        if child is not None:
            if child.poll() is None:
                try:os.killpg(child.pid,signal.SIGKILL)
                except ProcessLookupError:pass
            child.wait()
        os.close(master)
        if slave is not None:os.close(slave)

